/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type ChatGPTOverlayProps = Record<string, any>;

const ChatGPTOverlay: React.FC<ChatGPTOverlayProps> = ({
  backgroundColor = "#212121",
  transparentBackground = false,
  durationInSeconds = 10,
  userPrompt = "How to create motion graphics overlays using AI?",
  aiResponse = "The easiest way is to use Malloy Studio — just type a prompt, generate your animation, and export it as a transparent MOV file ready to drop into any video editor. No After Effects, no design experience needed.",
  accentColor = "#ececec",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Layout Metrics
  const safePaddingX = width * 0.05;
  const inputBoxBottomMargin = height * 0.04;
  const inputBoxMinHeight = height * 0.07;
  const fontSizeBase = width * 0.038;
  const avatarSize = width * 0.08;

  // Timings (Frame-based for deterministic rendering)
  const idleStartDelay = Math.round(fps * 0.6); // Wait before typing
  const userTypingSpeed = 1.2; // Frames per character
  const userTypingDuration = Math.round(userPrompt.length * userTypingSpeed);
  const userTypingEnd = idleStartDelay + userTypingDuration;
  
  const sendWait = Math.round(fps * 0.5); // Pause before hitting send
  const sendClickFrame = userTypingEnd + sendWait;
  
  const userMsgAppearFrame = sendClickFrame + 2; // Immediate appear and float
  const aiThinkingStart = userMsgAppearFrame + Math.round(fps * 0.6); // Wait for float to finish
  const aiThinkingDuration = Math.round(fps * 1.5); // 3 dots pulsing
  
  const aiResponseStart = aiThinkingStart + aiThinkingDuration;
  const words = aiResponse.split(" ");
  const framesPerWord = 2.5; // Streaming speed
  const aiResponseDuration = Math.round(words.length * framesPerWord);
  const aiResponseEnd = aiResponseStart + aiResponseDuration;

  // --- Interpolations ---

  // 1. Input Box State
  const charsToShow = Math.floor(
    interpolate(frame, [idleStartDelay, userTypingEnd], [0, userPrompt.length], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );
  const isSent = frame >= sendClickFrame;
  const currentInputText = isSent ? "" : userPrompt.substring(0, charsToShow);
  
  const showInputPlaceholder = charsToShow === 0 && !isSent;
  const cursorBlink = Math.floor(frame / 15) % 2 === 0;
  const showInputCursor = !isSent && cursorBlink;

  // Send Button Animation
  const isSendActive = charsToShow > 0 && !isSent;
  const sendScale = interpolate(
    frame,
    [sendClickFrame, sendClickFrame + 3, sendClickFrame + 6],
    [1, 0.8, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const sendOpacity = isSent ? 0 : interpolate(charsToShow, [0, 1], [0.3, 1], { extrapolateRight: "clamp" });

  // 2. User Bubble (Floats up)
  const userBubbleProgress = spring({
    frame: frame - userMsgAppearFrame,
    fps,
    config: { damping: 14, stiffness: 120 },
  });
  
  // Slide up from input area
  const userBubbleY = interpolate(userBubbleProgress, [0, 1], [height * 0.15, 0]);
  const userBubbleOpacity = interpolate(userBubbleProgress, [0, 1], [0, 1]);

  // 3. AI State
  const showAiThinking = frame >= aiThinkingStart && frame < aiResponseStart;
  const showAiResponse = frame >= aiResponseStart;

  // Pulsing Dots
  const dot1 = Math.sin((frame - aiThinkingStart) * 0.2) * 0.5 + 0.5;
  const dot2 = Math.sin((frame - aiThinkingStart - 4) * 0.2) * 0.5 + 0.5;
  const dot3 = Math.sin((frame - aiThinkingStart - 8) * 0.2) * 0.5 + 0.5;

  // Word Streaming
  const wordsToShow = Math.floor(
    interpolate(frame, [aiResponseStart, aiResponseEnd], [0, words.length], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );
  const currentAiText = words.slice(0, wordsToShow).join(" ");
  const showAiCursor = frame >= aiResponseStart && frame <= aiResponseEnd + fps;

  // Visuals Logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, color: "#ececec" }}>
      
      {/* Chat History Area */}
      <div style={{
        position: "absolute",
        top: 0,
        left: 0,
        right: 0,
        bottom: inputBoxBottomMargin + inputBoxMinHeight + height * 0.05,
        display: "flex",
        flexDirection: "column",
        justifyContent: "flex-end",
        padding: safePaddingX,
        gap: height * 0.03,
      }}>
        
        {/* User Message */}
        {frame >= userMsgAppearFrame && (
          <div style={{
            display: "flex",
            justifyContent: "flex-end",
            transform: `translateY(${userBubbleY}px)`,
            opacity: userBubbleOpacity,
          }}>
            <div style={{
              backgroundColor: "#2f2f2f",
              padding: `${width * 0.035}px ${width * 0.045}px`,
              borderRadius: width * 0.05,
              maxWidth: "85%",
              fontSize: fontSizeBase,
              lineHeight: 1.5,
              wordWrap: "break-word",
              whiteSpace: "pre-wrap"
            }}>
              {userPrompt}
            </div>
          </div>
        )}

        {/* AI Message */}
        {(showAiThinking || showAiResponse) && (
          <div style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "flex-start",
            gap: width * 0.03,
            maxWidth: "95%",
          }}>
            {/* AI Avatar */}
            <div style={{
              width: avatarSize,
              height: avatarSize,
              backgroundColor: "#10a37f", // Native ChatGPT Green
              borderRadius: "50%",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              flexShrink: 0,
            }}>
              <svg width="60%" height="60%" viewBox="0 0 24 24" fill="white">
                <path d="M12 2L14.4 9.6L22 12L14.4 14.4L12 22L9.6 14.4L2 12L9.6 9.6L12 2Z" />
              </svg>
            </div>

            {/* AI Content */}
            <div style={{
              fontSize: fontSizeBase,
              lineHeight: 1.6,
              paddingTop: width * 0.015,
              flex: 1,
            }}>
              
              {/* Thinking Indicator */}
              {showAiThinking && (
                <div style={{ display: "flex", gap: 6, height: fontSizeBase, alignItems: "center" }}>
                  <div style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: "#888", opacity: dot1 }} />
                  <div style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: "#888", opacity: dot2 }} />
                  <div style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: "#888", opacity: dot3 }} />
                </div>
              )}

              {/* Streaming Response */}
              {showAiResponse && (
                <div style={{ wordWrap: "break-word", whiteSpace: "pre-wrap" }}>
                  {currentAiText}
                  {showAiCursor && (
                    <span style={{
                      display: "inline-block",
                      width: width * 0.03,
                      height: fontSizeBase,
                      backgroundColor: "#ececec",
                      borderRadius: 2,
                      marginLeft: 6,
                      verticalAlign: "middle",
                      opacity: cursorBlink ? 1 : 0
                    }} />
                  )}
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Background block behind input to mask chat history sliding up */}
      <div style={{
        position: "absolute",
        bottom: 0,
        left: 0,
        right: 0,
        height: inputBoxBottomMargin + inputBoxMinHeight + height * 0.04,
        background: `linear-gradient(to top, ${backgroundColor} 80%, ${backgroundColor}00 100%)`,
        pointerEvents: "none",
      }} />

      {/* Input Box Area */}
      <div style={{
        position: "absolute",
        bottom: inputBoxBottomMargin,
        left: safePaddingX,
        right: safePaddingX,
        backgroundColor: "#2f2f2f",
        borderRadius: width * 0.06,
        padding: `${width * 0.03}px ${width * 0.04}px`,
        display: "flex",
        flexDirection: "row",
        alignItems: "center",
        border: "1px solid #444",
        minHeight: inputBoxMinHeight,
      }}>
        <div style={{
          flex: 1,
          color: showInputPlaceholder ? "#888" : "#ececec",
          fontSize: fontSizeBase,
          lineHeight: 1.4,
          display: "flex",
          alignItems: "center",
          whiteSpace: "nowrap",
          overflow: "hidden"
        }}>
          {showInputPlaceholder ? "Message..." : currentInputText}
          {showInputCursor && (
            <span style={{
              width: 2,
              height: fontSizeBase * 1.2,
              backgroundColor: accentColor,
              display: "inline-block",
              marginLeft: 4,
            }} />
          )}
        </div>

        {/* Send Button */}
        <div style={{
          width: width * 0.08,
          height: width * 0.08,
          backgroundColor: isSendActive ? accentColor : "#444",
          borderRadius: "50%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          marginLeft: width * 0.03,
          transform: `scale(${sendScale})`,
          opacity: sendOpacity,
          flexShrink: 0,
        }}>
          <svg width="50%" height="50%" viewBox="0 0 24 24" fill="none" stroke={isSendActive ? "#2f2f2f" : "#888"} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <path d="M12 19V5M5 12l7-7 7 7" />
          </svg>
        </div>
      </div>

    </AbsoluteFill>
  );
};

export default ChatGPTOverlay;